// MARK: - Errors

/// Error enum for DevOpsAgent
public struct DevOpsAgentErrorType: AWSErrorType {
    enum Code: String {
        case accessDeniedException = "AccessDeniedException"
        case conflictException = "ConflictException"
        case contentSizeExceededException = "ContentSizeExceededException"
        case identityCenterServiceException = "IdentityCenterServiceException"
        case internalServerException = "InternalServerException"
        case invalidParameterException = "InvalidParameterException"
        case resourceNotFoundException = "ResourceNotFoundException"
        case serviceQuotaExceededException = "ServiceQuotaExceededException"
        case throttlingException = "ThrottlingException"
        case validationException = "ValidationException"
    }

    private let error: Code
    public let context: AWSErrorContext?

    /// initialize DevOpsAgent
    public init?(errorCode: String, context: AWSErrorContext) {
        guard let error = Code(rawValue: errorCode) else { return nil }
        self.error = error
        self.context = context
    }

    internal init(_ error: Code) {
        self.error = error
        self.context = nil
    }

    /// return error code string
    public var errorCode: String { self.error.rawValue }

    /// Access to the requested resource is denied due to insufficient permissions.
    public static var accessDeniedException: Self { .init(.accessDeniedException) }
    /// The request conflicts with the current state of the resource.
    public static var conflictException: Self { .init(.conflictException) }
    /// This exception is thrown when the content size exceeds the allowed limit.
    public static var contentSizeExceededException: Self { .init(.contentSizeExceededException) }
    /// Calls to the customer Identity Center have failed
    public static var identityCenterServiceException: Self { .init(.identityCenterServiceException) }
    /// This exception is thrown when an unexpected error occurs in the processing of a request.
    public static var internalServerException: Self { .init(.internalServerException) }
    /// One or more parameters provided in the request are invalid.
    public static var invalidParameterException: Self { .init(.invalidParameterException) }
    /// The requested resource could not be found.
    public static var resourceNotFoundException: Self { .init(.resourceNotFoundException) }
    /// The request would exceed the service quota limit.
    public static var serviceQuotaExceededException: Self { .init(.serviceQuotaExceededException) }
    /// The request was throttled due to too many requests. Please slow down and try again.
    public static var throttlingException: Self { .init(.throttlingException) }
    /// The input fails to satisfy the constraints specified by the service.
    public static var validationException: Self { .init(.validationException) }
}

extension DevOpsAgentErrorType: AWSServiceErrorType {
    public static let errorCodeMap: [String: AWSErrorShape.Type] = [
        "IdentityCenterServiceException": DevOpsAgent.IdentityCenterServiceException.self,
        "ValidationException": DevOpsAgent.ValidationException.self
    ]
}

extension DevOpsAgentErrorType: Equatable {
    public static func == (lhs: DevOpsAgentErrorType, rhs: DevOpsAgentErrorType) -> Bool {
        lhs.error == rhs.error
    }
}

extension DevOpsAgentErrorType: CustomStringConvertible {
    public var description: String {
        return "\(self.error.rawValue): \(self.message ?? "")"
    }
}
